package com.vishatech.erp.controller;
import com.vishatech.erp.dto.ApiResponse;import com.vishatech.erp.service.*;import java.util.*;import org.springframework.data.domain.Page;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/purchase")
public class PurchaseReceivingController{
 private final PurchaseReceivingService s;private final PurchaseSupportService support;public PurchaseReceivingController(PurchaseReceivingService s,PurchaseSupportService p){this.s=s;support=p;}
 @PostMapping("/grns") @PreAuthorize("hasAuthority('PURCHASE_CREATE')") public ResponseEntity<ApiResponse<Map<String,Object>>> create(@RequestBody Map<String,Object>r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.ok(s.createGrn(r)));}
 /*
  * List endpoints below are PAGED: page (0-based), size (default 25, hard
  * max 100), optional search/filters and a whitelisted sort field. They
  * return a Spring Page — { content, page, size, totalElements, totalPages }
  * — so a client can never pull the whole table in one request.
  */
 @GetMapping("/grns") @PreAuthorize("hasAuthority('PURCHASE_VIEW')") public Page<Map<String,Object>> listGrns(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="25") int size,@RequestParam(required=false) String search,@RequestParam(required=false) String status,@RequestParam(required=false) String vendor,@RequestParam(required=false) String poNo,@RequestParam(required=false) String sort){return s.listGrns(page,size,search,status,vendor,poNo,sort);}
 @GetMapping("/grns/stats") @PreAuthorize("hasAuthority('PURCHASE_VIEW')") public ResponseEntity<ApiResponse<Map<String,Object>>> grnStats(){return ResponseEntity.ok(ApiResponse.ok(s.grnStats()));}
 @GetMapping("/grns/next-number") @PreAuthorize("hasAuthority('PURCHASE_VIEW')") public ResponseEntity<ApiResponse<Map<String,Object>>> nextGrnNumber(){return ResponseEntity.ok(ApiResponse.ok(s.nextGrnNumber()));}
 @PostMapping("/grns/{id}/receive") @PreAuthorize("hasAuthority('PURCHASE_EDIT')") public ResponseEntity<ApiResponse<Map<String,Object>>> receive(@PathVariable String id,@RequestBody(required=false) Map<String,Object>r){Object raw=r==null?null:r.get("items");List<Map<String,Object>> items=raw instanceof List<?> l?(List<Map<String,Object>>)(List<?>)l:List.of();return ResponseEntity.ok(ApiResponse.ok(s.receive(id,items)));}
 @GetMapping("/grns/{id}") @PreAuthorize("hasAuthority('PURCHASE_VIEW')") public ResponseEntity<ApiResponse<Map<String,Object>>> get(@PathVariable String id){return ResponseEntity.ok(ApiResponse.ok(s.getGrnResponse(id)));}
 @PatchMapping("/grns/{id}") @PreAuthorize("hasAuthority('PURCHASE_EDIT')") public ResponseEntity<ApiResponse<Map<String,Object>>> updateGrn(@PathVariable String id,@RequestBody Map<String,Object>r){return ResponseEntity.ok(ApiResponse.ok(s.updateGrn(id,r)));}
 @PostMapping("/inspections") @PreAuthorize("hasAuthority('PURCHASE_CREATE')") public ResponseEntity<ApiResponse<Map<String,Object>>> inspect(@RequestBody Map<String,Object>r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.ok(s.createInspection(r)));}
 @GetMapping("/inspections") @PreAuthorize("hasAuthority('PURCHASE_VIEW')") public Page<Map<String,Object>> listInspections(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="25") int size,@RequestParam(required=false) String search,@RequestParam(required=false) String status,@RequestParam(required=false) String grnNo,@RequestParam(required=false) String sort){return s.listInspections(page,size,search,status,grnNo,sort);}
 @GetMapping("/inspections/stats") @PreAuthorize("hasAuthority('PURCHASE_VIEW')") public ResponseEntity<ApiResponse<Map<String,Object>>> inspectionStats(){return ResponseEntity.ok(ApiResponse.ok(s.inspectionStats()));}
 @GetMapping("/inspections/{id}") @PreAuthorize("hasAuthority('PURCHASE_VIEW')") public ResponseEntity<ApiResponse<Map<String,Object>>> getInspection(@PathVariable String id){return ResponseEntity.ok(ApiResponse.ok(s.getInspection(id)));}
 @PatchMapping("/inspections/{id}") @PreAuthorize("hasAuthority('PURCHASE_EDIT')") public ResponseEntity<ApiResponse<Map<String,Object>>> update(@PathVariable Long id,@RequestBody Map<String,Object>r){return ResponseEntity.ok(ApiResponse.ok(s.updateInspection(id,r)));}
 // ==================== Manufacturing / Packing ====================
 @PostMapping("/manufacturing") @PreAuthorize("hasAuthority('PURCHASE_CREATE')") public ResponseEntity<ApiResponse<Map<String,Object>>> createMfg(@RequestBody Map<String,Object>r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.ok(s.createManufacturingJob(r)));}
 @GetMapping("/manufacturing") @PreAuthorize("hasAuthority('PURCHASE_VIEW')") public Page<Map<String,Object>> listMfg(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="25") int size,@RequestParam(required=false) String search,@RequestParam(required=false) String status,@RequestParam(required=false) String poNo,@RequestParam(required=false) String sort){return s.listManufacturing(page,size,search,status,poNo,sort);}
 @GetMapping("/manufacturing/stats") @PreAuthorize("hasAuthority('PURCHASE_VIEW')") public ResponseEntity<ApiResponse<Map<String,Object>>> mfgStats(){return ResponseEntity.ok(ApiResponse.ok(s.manufacturingStats()));}
 @GetMapping("/manufacturing/next-number") @PreAuthorize("hasAuthority('PURCHASE_VIEW')") public ResponseEntity<ApiResponse<Map<String,Object>>> nextMfgNumber(){return ResponseEntity.ok(ApiResponse.ok(s.nextMfrNumber()));}
 @GetMapping("/manufacturing/{id}") @PreAuthorize("hasAuthority('PURCHASE_VIEW')") public ResponseEntity<ApiResponse<Map<String,Object>>> getMfg(@PathVariable Long id){return ResponseEntity.ok(ApiResponse.ok(s.getManufacturing(id)));}
 @PatchMapping("/manufacturing/{id}") @PreAuthorize("hasAuthority('PURCHASE_EDIT')") public ResponseEntity<ApiResponse<Map<String,Object>>> updateMfg(@PathVariable Long id,@RequestBody Map<String,Object>r){return ResponseEntity.ok(ApiResponse.ok(s.updateManufacturing(id,r)));}
 // ==================== Shipments ====================
 @PostMapping("/shipments") @PreAuthorize("hasAuthority('PURCHASE_CREATE')") public ResponseEntity<ApiResponse<Map<String,Object>>> createShip(@RequestBody Map<String,Object>r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.ok(s.createShipment(r)));}
 @GetMapping("/shipments") @PreAuthorize("hasAuthority('PURCHASE_VIEW')") public Page<Map<String,Object>> listShips(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="25") int size,@RequestParam(required=false) String search,@RequestParam(required=false) String status,@RequestParam(required=false) String poNo,@RequestParam(required=false) String vendor,@RequestParam(required=false) String sort){return s.listShipments(page,size,search,status,poNo,vendor,sort);}
 @GetMapping("/shipments/stats") @PreAuthorize("hasAuthority('PURCHASE_VIEW')") public ResponseEntity<ApiResponse<Map<String,Object>>> shipStats(){return ResponseEntity.ok(ApiResponse.ok(s.shipmentStats()));}
 @GetMapping("/shipments/{id}") @PreAuthorize("hasAuthority('PURCHASE_VIEW')") public ResponseEntity<ApiResponse<Map<String,Object>>> getShip(@PathVariable Long id){return ResponseEntity.ok(ApiResponse.ok(s.getShipment(id)));}
 @PatchMapping("/shipments/{id}") @PreAuthorize("hasAuthority('PURCHASE_EDIT')") public ResponseEntity<ApiResponse<Map<String,Object>>> updateShip(@PathVariable Long id,@RequestBody Map<String,Object>r){return ResponseEntity.ok(ApiResponse.ok(s.updateShipment(id,r)));}
 // ==================== Inventory Update ====================
 @GetMapping("/inventory") @PreAuthorize("hasAuthority('PURCHASE_VIEW')") public Page<Map<String,Object>> listInv(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="25") int size,@RequestParam(required=false) String search,@RequestParam(required=false) String type,@RequestParam(required=false) String warehouse,@RequestParam(required=false) String sku,@RequestParam(required=false) String product,@RequestParam(required=false) String reference,@RequestParam(required=false) String inspectionNo,@RequestParam(required=false) String sort){return s.listInventory(page,size,search,type,warehouse,sku,product,reference,inspectionNo,sort);}
 @GetMapping("/inventory/stats") @PreAuthorize("hasAuthority('PURCHASE_VIEW')") public ResponseEntity<ApiResponse<Map<String,Object>>> invStats(){return ResponseEntity.ok(ApiResponse.ok(s.inventoryStats()));}
 @GetMapping("/inventory/ledger") @PreAuthorize("hasAuthority('PURCHASE_VIEW')") public ResponseEntity<ApiResponse<Map<String,Object>>> invLedger(@RequestParam(required=false) String sku,@RequestParam(required=false) String product,@RequestParam(required=false) String warehouse){return ResponseEntity.ok(ApiResponse.ok(s.inventoryLedger(sku,product,warehouse)));}
 @GetMapping("/inventory/by-inspection/{inspectionNo}") @PreAuthorize("hasAuthority('PURCHASE_VIEW')") public ResponseEntity<ApiResponse<List<Map<String,Object>>>> invByInspection(@PathVariable String inspectionNo){return ResponseEntity.ok(ApiResponse.ok(s.inventoryByInspection(inspectionNo)));}
 @PostMapping("/inventory") @PreAuthorize("hasAuthority('PURCHASE_CREATE')") public ResponseEntity<ApiResponse<Map<String,Object>>> createInv(@RequestBody Map<String,Object>r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.ok(s.createInventoryMovement(r)));}
 @PostMapping("/inventory/transfer") @PreAuthorize("hasAuthority('PURCHASE_CREATE')") public ResponseEntity<ApiResponse<Map<String,Object>>> transferInv(@RequestBody Map<String,Object>r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.ok(s.transferInventory(r)));}
 @PostMapping("/inventory/{id}/reverse") @PreAuthorize("hasAuthority('PURCHASE_EDIT')") public ResponseEntity<ApiResponse<Map<String,Object>>> reverseInv(@PathVariable String id,@RequestBody(required=false) Map<String,Object>r){return ResponseEntity.ok(ApiResponse.ok(s.reverseInventoryMovement(id,r==null?Map.of():r)));}
 @GetMapping("/inventory/{id}") @PreAuthorize("hasAuthority('PURCHASE_VIEW')") public ResponseEntity<ApiResponse<Map<String,Object>>> getInv(@PathVariable String id){return ResponseEntity.ok(ApiResponse.ok(s.getInventoryMovement(id)));}
}
